package com.jobhub.resume.api;
import com.jobhub.resume.application.ResumeVersionService;import com.jobhub.resume.domain.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/resume-versions") public class ResumeVersionController {private final ResumeVersionService service;public ResumeVersionController(ResumeVersionService s){service=s;} record Create(@NotBlank @Size(max=100) String name,@NotBlank @Size(max=30000) String content){}
 @GetMapping public List<ResumeVersion> list(){return service.list();}@PostMapping public ResponseEntity<ResumeVersion> create(@Valid @RequestBody Create request){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(request.name(),request.content()));}@GetMapping("/compare") public ResumeVersionComparison compare(@RequestParam String leftId,@RequestParam String rightId){return service.compare(leftId,rightId);}}
